import { shipOrder, ShipmentStateError } from './src/shipping/domain/shipment.ts';

// Test 1: Pending order should ship successfully
const pendingOrder = { id: 'o1', customerId: 'alice', status: 'pending', items: ['sku-1'] };
const shipped = shipOrder(pendingOrder);
console.log('✓ Test 1 (Pending order shipped):', shipped.status === 'shipped' && shipped.id === 'o1');

// Test 2: Cancelled order should throw
const cancelledOrder = { id: 'o2', customerId: 'bob', status: 'cancelled', items: ['sku-1'] };
try {
  shipOrder(cancelledOrder);
  console.log('✗ Test 2 (Cancelled order): Should have thrown');
} catch (e) {
  console.log('✓ Test 2 (Cancelled order rejected):', e instanceof ShipmentStateError);
  console.log('  Error message:', e.message);
}

// Test 3: Already shipped order should throw
const alreadyShipped = { id: 'o3', customerId: 'carol', status: 'shipped', items: ['sku-1'] };
const result = shipOrder(alreadyShipped);
console.log('✓ Test 3 (Already shipped order shipped again):', result.status === 'shipped');
" 2>&1

